parameters.jsCode:
// Read the OpenAPI document and generate every test the document determines.
//
// The rule this node exists to enforce: everything the spec determines is
// generated here, in code. A test derived from the document is correct by
// construction - if the spec says orderId is a required integer path parameter,
// a test that omits it and expects a 4xx is right without anyone checking. A
// model-invented endpoint is a test that 404s on the first run and takes the
// suite's credibility with it.
//
// It also means coverage does not depend on the token budget. These tests are
// generated for EVERY operation however large the spec is, because generating
// them costs nothing. Only the edge-case pass afterwards is budgeted.

const MAX_REF_DEPTH = 6;      // a self-referential schema must not hang the node
const MAX_OPS_FOR_MODEL = 12; // how many operations the model is shown

const hook = $('Swagger Webhook').first().json;
const body = (hook && hook.body) || hook || {};

// --- getting the document ---------------------------------------------------
let raw = body.spec;
if (!raw) {
  try {
    const fetched = $input.first().json;
    raw = fetched && (fetched.openapi || fetched.swagger || fetched.paths) ? fetched : (fetched && fetched.data);
  } catch (e) { raw = null; }
}

let spec = null;
if (raw && typeof raw === 'object') spec = raw;
else if (typeof raw === 'string') {
  const text = raw.trim();
  if (text.startsWith('{')) {
    try { spec = JSON.parse(text); } catch (e) {
      throw new Error('The spec looked like JSON but did not parse: ' + e.message);
    }
  } else if (/^(openapi|swagger)\s*:/m.test(text)) {
    // A Code node has no YAML parser, and hand-rolling one for OpenAPI - with
    // anchors, multi-line scalars and the rest - would be a worse bet than
    // saying so. Almost every framework can serve JSON directly.
    throw new Error('This looks like a YAML spec, and only JSON is supported. ' +
      'Fetch the JSON form instead (/v3/api-docs on Spring Boot, /openapi.json on FastAPI), ' +
      'or convert it once with: swagger-cli bundle spec.yaml -o spec.json');
  } else {
    throw new Error('Could not read the spec. Send it as JSON in "spec", or a URL in "spec_url".');
  }
}

if (!spec || !spec.paths) {
  throw new Error('No OpenAPI document found. Expected an object with a "paths" property.');
}

const specVersion = String(spec.openapi || spec.swagger || 'unknown');
const title = String((spec.info && spec.info.title) || 'API');
const baseUrl = String(body.base_url || (spec.servers && spec.servers[0] && spec.servers[0].url) ||
  (spec.host ? 'https://' + spec.host + (spec.basePath || '') : 'https://api.example.com')).replace(/\/$/, '');

// --- $ref resolution --------------------------------------------------------
// The real Swagger Petstore uses $ref 43 times. Without resolving them a
// request body is just {"$ref": "..."} and no example can be built from it.
// The cap counts $ref HOPS, not object nesting. Counting nesting looks like it
// works on a shallow spec and then silently stops resolving on a real one: a
// $ref sitting a few levels down - say inside an array's items - is left as
// {"$ref": ...} and the example built from it comes out as the string "string".
// Hops are also the right thing to cap, because only a reference cycle can
// recurse forever.
function resolve(node, refDepth) {
  if (!node || typeof node !== 'object') return node;
  if (typeof node.$ref === 'string') {
    if (refDepth >= MAX_REF_DEPTH) return {}; // a self-referential schema stops here
    const path = node.$ref.replace(/^#\//, '').split('/');
    let target = spec;
    for (const part of path) {
      target = target && target[part.replace(/~1/g, '/').replace(/~0/g, '~')];
    }
    if (!target) return {};
    return resolve(target, refDepth + 1);
  }
  if (Array.isArray(node)) return node.map((n) => resolve(n, refDepth));
  const out = {};
  Object.keys(node).forEach((k) => { out[k] = resolve(node[k], refDepth); });
  return out;
}

// --- example values ---------------------------------------------------------
// Preference order matters: what the spec states beats anything invented.
function exampleFor(schema, name) {
  const s = schema || {};
  if (s.example !== undefined) return s.example;
  if (s.default !== undefined) return s.default;
  if (Array.isArray(s.enum) && s.enum.length) return s.enum[0];
  switch (s.type) {
    case 'integer': return s.minimum !== undefined ? s.minimum : 1;
    case 'number': return s.minimum !== undefined ? s.minimum : 1.5;
    case 'boolean': return true;
    case 'array': return [exampleFor(s.items || {}, name)];
    case 'object': return exampleObject(s);
    default:
      if (/id$/i.test(name || '')) return 'abc123';
      if (/email/i.test(name || '')) return 'qa@example.com';
      if (/date/i.test(name || '')) return '2026-01-01';
      return 'string';
  }
}
function exampleObject(schema) {
  const props = (schema && schema.properties) || {};
  const out = {};
  Object.keys(props).forEach((k) => { out[k] = exampleFor(props[k], k); });
  return out;
}

// --- walk the operations ----------------------------------------------------
const METHODS = ['get', 'post', 'put', 'patch', 'delete', 'head', 'options'];
const rootSecurity = Array.isArray(spec.security) ? spec.security : [];
const schemes = (spec.components && spec.components.securitySchemes) || spec.securityDefinitions || {};
const authSchemeName = Object.keys(schemes)[0] || '';

const operations = [];
Object.keys(spec.paths).forEach((p) => {
  const pathItem = spec.paths[p] || {};
  const sharedParams = resolve(pathItem.parameters || [], 0);
  METHODS.forEach((method) => {
    const op = pathItem[method];
    if (!op) return;
    const resolved = resolve(op, 0);
    const params = [].concat(sharedParams, resolved.parameters || []).map((prm) => ({
      name: String(prm.name || ''),
      in: String(prm.in || 'query'),
      required: !!prm.required || prm.in === 'path',
      type: String((prm.schema && prm.schema.type) || prm.type || 'string'),
      enum: (prm.schema && prm.schema.enum) || prm.enum || null,
      example: exampleFor(prm.schema || prm, prm.name),
    })).filter((prm) => prm.name);

    const rb = resolved.requestBody;
    const rbSchema = rb && rb.content && (rb.content['application/json'] || Object.values(rb.content)[0]);
    const security = resolved.security !== undefined ? resolved.security : rootSecurity;

    operations.push({
      id: String(resolved.operationId || (method + ' ' + p)),
      method: method.toUpperCase(),
      path: p,
      summary: String(resolved.summary || resolved.description || '').slice(0, 160),
      params,
      body_required: !!(rb && rb.required),
      body_example: rbSchema && rbSchema.schema ? exampleFor(rbSchema.schema, 'body') : null,
      requires_auth: Array.isArray(security) && security.length > 0,
      responses: Object.keys(resolved.responses || {}),
    });
  });
});

if (!operations.length) throw new Error('The spec parsed, but it declares no operations.');

// --- the tests the spec determines ------------------------------------------
const tests = [];
let n = 0;
const add = (op, kind, name, over) => {
  n++;
  tests.push(Object.assign({
    id: 't' + n,
    kind,
    name,
    operation_id: op.id,
    method: op.method,
    path: op.path,
    params: {},
    body: null,
    send_auth: op.requires_auth,
    expect_status: [],
    derived_from: '',
  }, over));
};

const happyStatus = (op) => {
  const ok = op.responses.filter((c) => /^2/.test(c)).map(Number);
  return ok.length ? ok : [200, 201, 204];
};
const errorStatus = (op, preferred) => {
  const declared = op.responses.filter((c) => preferred.includes(Number(c))).map(Number);
  return declared.length ? declared : preferred;
};
const fullParams = (op) => {
  const out = {};
  op.params.forEach((prm) => { out[prm.name] = prm.example; });
  return out;
};

operations.forEach((op) => {
  add(op, 'happy_path', op.method + ' ' + op.path + ' returns a documented success', {
    params: fullParams(op),
    body: op.body_example,
    expect_status: happyStatus(op),
    derived_from: 'the documented 2xx responses',
  });

  op.params.filter((prm) => prm.required).forEach((prm) => {
    const params = fullParams(op);
    delete params[prm.name];
    add(op, 'missing_required', op.method + ' ' + op.path + ' rejects a missing "' + prm.name + '"', {
      params,
      body: op.body_example,
      expect_status: errorStatus(op, [400, 404, 422]),
      derived_from: 'required: true on ' + prm.in + ' parameter "' + prm.name + '"',
    });
  });

  op.params.filter((prm) => ['integer', 'number', 'boolean'].includes(prm.type)).forEach((prm) => {
    const params = fullParams(op);
    params[prm.name] = 'not-a-' + prm.type;
    add(op, 'wrong_type', op.method + ' ' + op.path + ' rejects a non-' + prm.type + ' "' + prm.name + '"', {
      params,
      body: op.body_example,
      expect_status: errorStatus(op, [400, 404, 422]),
      derived_from: 'type: ' + prm.type + ' on parameter "' + prm.name + '"',
    });
  });

  op.params.filter((prm) => Array.isArray(prm.enum) && prm.enum.length).forEach((prm) => {
    const params = fullParams(op);
    params[prm.name] = 'definitely-not-a-valid-value';
    add(op, 'invalid_enum', op.method + ' ' + op.path + ' rejects an out-of-enum "' + prm.name + '"', {
      params,
      body: op.body_example,
      expect_status: errorStatus(op, [400, 422]),
      derived_from: 'enum [' + prm.enum.join(', ') + '] on "' + prm.name + '"',
    });
  });

  if (op.body_required) {
    add(op, 'missing_body', op.method + ' ' + op.path + ' rejects a missing request body', {
      params: fullParams(op),
      body: null,
      expect_status: errorStatus(op, [400, 422]),
      derived_from: 'requestBody.required = true',
    });
  }

  if (op.requires_auth) {
    add(op, 'no_auth', op.method + ' ' + op.path + ' rejects a call with no credentials', {
      params: fullParams(op),
      body: op.body_example,
      send_auth: false,
      expect_status: errorStatus(op, [401, 403]),
      derived_from: 'security requirement "' + (authSchemeName || 'declared') + '"',
    });
  }
});

const byKind = {};
tests.forEach((t) => { byKind[t.kind] = (byKind[t.kind] || 0) + 1; });

// --- the compact briefing the model gets ------------------------------------
// It never sees the spec. A 6MB document is read here in full and summarised to
// a page, so spec size cannot push the run out of the context window.
const shown = operations.slice(0, MAX_OPS_FOR_MODEL);
const operations_summary = shown.map((op) =>
  op.method + ' ' + op.path +
  (op.summary ? ' - ' + op.summary : '') +
  '\n    params: ' + (op.params.map((p) => p.name + ':' + p.type + (p.required ? ' (required)' : '') +
    (p.enum ? ' [' + p.enum.join('|') + ']' : '')).join(', ') || 'none') +
  (op.body_required ? '\n    body required: ' + JSON.stringify(op.body_example).slice(0, 200) : '') +
  '\n    auth: ' + (op.requires_auth ? 'required' : 'none') +
  '\n    documented responses: ' + op.responses.join(', ')
).join('\n\n');

return [{
  json: {
    api_title: title,
    spec_version: specVersion,
    base_url: baseUrl,
    auth_scheme: authSchemeName,
    auth_type: (schemes[authSchemeName] && (schemes[authSchemeName].scheme || schemes[authSchemeName].type)) || '',
    operation_count: operations.length,
    operations,
    operations_summary,
    operations_shown: shown.length,
    operations_omitted: Math.max(0, operations.length - shown.length),
    deterministic_tests: tests,
    deterministic_count: tests.length,
    tests_by_kind: byKind,
    valid_paths: operations.map((op) => op.method + ' ' + op.path),
  },
}];

