parameters.jsCode:
// Check the model's scenarios against the specification, then assemble both
// artefacts: a Postman v2.1 collection and a RestAssured JUnit class.
//
// The check is the point. A scenario naming a path or a parameter that is not
// in the document produces a test that fails on its first run, and a suite
// whose first few tests fail on their first run gets deleted along with any
// trust in the tool. So the spec, not the model, decides what exists.

const spec = $('Parse Spec').first().json;

let model = {};
try {
  const incoming = $input.first().json;
  model = (incoming && incoming.output) || incoming || {};
} catch (e) { model = {}; }
if (typeof model !== 'object' || Array.isArray(model)) model = {};

const notes = [];
const str = (v, f) => { const s = String(v === undefined || v === null ? '' : v).trim(); return s || f; };
const arr = (v) => (Array.isArray(v) ? v : []);

const opIndex = {};
spec.operations.forEach((op) => { opIndex[op.method + ' ' + op.path] = op; });

// --- the guard rail ---------------------------------------------------------
let droppedUnknownPath = 0;
let droppedUnknownParam = 0;
const rejected = [];

const scenarios = arr(model.scenarios).map((s) => ({
  name: str(s && s.name, ''),
  method: str(s && s.method, '').toUpperCase(),
  path: str(s && s.path, ''),
  why: str(s && s.why, 'Not Provided'),
  steps: arr(s && s.steps).map((x) => String(x).trim()).filter(Boolean),
  test_data: str(s && s.test_data, ''),
  expect: str(s && s.expect, 'Not Provided'),
  priority: ['High', 'Medium', 'Low'].find((p) => p.toLowerCase() === str(s && s.priority, '').toLowerCase()) || 'Medium',
})).filter((s) => {
  if (!s.name || !s.method || !s.path) { droppedUnknownPath++; return false; }
  const op = opIndex[s.method + ' ' + s.path];
  if (!op) {
    droppedUnknownPath++;
    rejected.push(s.method + ' ' + s.path + ' (no such operation)');
    return false;
  }
  // Any parameter the scenario names in its data must be declared on that
  // operation. Checked loosely - the model writes prose, not a param list.
  const declared = op.params.map((p) => p.name.toLowerCase());
  const invented = (s.test_data.match(/\b([a-zA-Z_][a-zA-Z0-9_]{2,})\s*[=:]/g) || [])
    .map((m) => m.replace(/\s*[=:]$/, '').toLowerCase())
    .filter((k) => !declared.includes(k) && !['id', 'body', 'status', 'response', 'value', 'data', 'token', 'items', 'sku', 'quantity', 'note', 'priority', 'customerid'].includes(k));
  if (invented.length > 2) {
    droppedUnknownParam++;
    rejected.push(s.name + ' (names undeclared fields: ' + invented.slice(0, 3).join(', ') + ')');
    return false;
  }
  return true;
});

if (droppedUnknownPath) notes.push(droppedUnknownPath + ' scenario(s) dropped for naming an operation the spec does not declare');
if (droppedUnknownParam) notes.push(droppedUnknownParam + ' scenario(s) dropped for naming undeclared fields');

// --- Postman v2.1 -----------------------------------------------------------
const tests = spec.deterministic_tests;

function urlFor(t) {
  let path = t.path;
  const query = [];
  const op = opIndex[t.method + ' ' + t.path] || { params: [] };
  Object.keys(t.params || {}).forEach((k) => {
    const p = op.params.find((x) => x.name === k);
    const v = t.params[k];
    if (p && p.in === 'path') path = path.replace('{' + k + '}', encodeURIComponent(String(v)));
    else if (p && p.in === 'header') { /* handled below */ }
    else query.push({ key: k, value: String(v) });
  });
  // A path parameter that was deliberately omitted leaves its placeholder; a
  // request to a literal "{orderId}" is exactly the 4xx the test is checking.
  const raw = '{{baseUrl}}' + path + (query.length ? '?' + query.map((q) => q.key + '=' + encodeURIComponent(q.value)).join('&') : '');
  return {
    raw,
    host: ['{{baseUrl}}'],
    path: path.replace(/^\//, '').split('/'),
    query,
  };
}

function headersFor(t) {
  const h = [];
  if (t.send_auth) h.push({ key: 'Authorization', value: 'Bearer {{authToken}}' });
  if (t.body) h.push({ key: 'Content-Type', value: 'application/json' });
  const op = opIndex[t.method + ' ' + t.path] || { params: [] };
  op.params.filter((p) => p.in === 'header').forEach((p) => {
    if (t.params && t.params[p.name] !== undefined) h.push({ key: p.name, value: String(t.params[p.name]) });
  });
  return h;
}

function scriptFor(t) {
  const list = JSON.stringify(t.expect_status);
  return [
    '// ' + t.derived_from,
    'pm.test("status is one of ' + t.expect_status.join(', ') + '", function () {',
    '    pm.expect(' + list + ').to.include(pm.response.code);',
    '});',
    'pm.test("responds within 3s", function () {',
    '    pm.expect(pm.response.responseTime).to.be.below(3000);',
    '});',
  ];
}

const folders = {};
tests.forEach((t) => {
  const key = t.kind;
  folders[key] = folders[key] || [];
  folders[key].push({
    name: t.name,
    request: {
      method: t.method,
      header: headersFor(t),
      url: urlFor(t),
      body: t.body ? { mode: 'raw', raw: JSON.stringify(t.body, null, 2), options: { raw: { language: 'json' } } } : undefined,
      description: t.derived_from,
    },
    event: [{ listen: 'test', script: { type: 'text/javascript', exec: scriptFor(t) } }],
  });
});

const FOLDER_TITLES = {
  happy_path: '1. Happy paths',
  missing_required: '2. Missing required parameters',
  wrong_type: '3. Wrong parameter types',
  invalid_enum: '4. Invalid enum values',
  missing_body: '5. Missing request bodies',
  no_auth: '6. Unauthenticated calls',
};

const collection = {
  info: {
    _postman_id: 'gen-' + Date.now().toString(36),
    name: spec.api_title + ' - generated baseline suite',
    description: [
      'Generated from the OpenAPI ' + spec.spec_version + ' document for ' + spec.api_title + '.',
      '',
      spec.deterministic_count + ' tests derived directly from the specification across ' +
        spec.operation_count + ' operations, plus ' + scenarios.length + ' scenario notes that a schema cannot imply.',
      '',
      'Set the baseUrl and authToken collection variables before running.',
      'Run with: newman run collection.json',
    ].join('\n'),
    schema: 'https://schema.getpostman.com/json/collection/v2.1.0/collection.json',
  },
  variable: [
    { key: 'baseUrl', value: spec.base_url, type: 'string' },
    { key: 'authToken', value: '', type: 'string' },
  ],
  item: Object.keys(folders).map((kind) => ({
    name: FOLDER_TITLES[kind] || kind,
    item: folders[kind],
  })),
};

// The scenarios go in as a folder of documented stubs rather than as executable
// requests: they are multi-step and need data set up first, so pretending they
// are runnable would be the same lie as an invented endpoint.
if (scenarios.length) {
  collection.item.push({
    name: '7. Scenarios to write by hand',
    description: 'These need state or sequencing that a generated request cannot express. Each names a real operation from the spec.',
    item: scenarios.map((s) => ({
      name: '[' + s.priority + '] ' + s.name,
      request: {
        method: s.method,
        header: [{ key: 'Authorization', value: 'Bearer {{authToken}}' }],
        url: urlFor({ method: s.method, path: s.path, params: {} }),
        description: [
          'WHY: ' + s.why,
          '',
          'STEPS:',
          s.steps.length ? s.steps.map((x, i) => '  ' + (i + 1) + '. ' + x).join('\n') : '  (single call)',
          '',
          'DATA: ' + (s.test_data || 'Not Provided'),
          'EXPECT: ' + s.expect,
        ].join('\n'),
      },
      event: [{ listen: 'test', script: { type: 'text/javascript', exec: [
        '// This scenario needs set-up and assertions a generator cannot write.',
        '// ' + s.expect.replace(/\n/g, ' '),
        'pm.test("TODO: implement - ' + s.name.replace(/"/g, "'") + '", function () {',
        '    pm.expect.fail("Not implemented yet");',
        '});',
      ] } }],
    })),
  });
}

// --- RestAssured ------------------------------------------------------------
const javaName = (s) => s.replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_+|_+$/g, '').replace(/^(\d)/, 't$1').slice(0, 80);
const javaClass = (spec.api_title.replace(/[^a-zA-Z0-9]/g, '') || 'Api') + 'BaselineTest';

const javaTests = tests.map((t) => {
  const op = opIndex[t.method + ' ' + t.path] || { params: [] };
  const lines = ['    @Test'];
  lines.push('    @DisplayName("' + t.name.replace(/"/g, "'") + '")');
  lines.push('    void ' + javaName(t.kind + '_' + t.operation_id + '_' + t.id) + '() {');
  lines.push('        given()');
  lines.push('            .baseUri(BASE_URL)');
  if (t.send_auth) lines.push('            .header("Authorization", "Bearer " + AUTH_TOKEN)');
  Object.keys(t.params || {}).forEach((k) => {
    const p = op.params.find((x) => x.name === k);
    const v = JSON.stringify(String(t.params[k]));
    if (p && p.in === 'path') lines.push('            .pathParam("' + k + '", ' + v + ')');
    else if (p && p.in === 'header') lines.push('            .header("' + k + '", ' + v + ')');
    else lines.push('            .queryParam("' + k + '", ' + v + ')');
  });
  if (t.body) {
    lines.push('            .contentType("application/json")');
    lines.push('            .body(' + JSON.stringify(JSON.stringify(t.body)) + ')');
  }
  lines.push('        .when()');
  lines.push('            .' + t.method.toLowerCase() + '("' + t.path + '")');
  lines.push('        .then()');
  lines.push('            .time(lessThan(3000L))');
  lines.push('            .statusCode(anyOf(' + t.expect_status.map((c) => 'is(' + c + ')').join(', ') + '));');
  lines.push('        // ' + t.derived_from);
  lines.push('    }');
  return lines.join('\n');
});

const restAssured = [
  'package com.aitester.api;',
  '',
  'import org.junit.jupiter.api.DisplayName;',
  'import org.junit.jupiter.api.Test;',
  '',
  'import static io.restassured.RestAssured.given;',
  'import static org.hamcrest.Matchers.anyOf;',
  'import static org.hamcrest.Matchers.is;',
  'import static org.hamcrest.Matchers.lessThan;',
  '',
  '/**',
  ' * Baseline API suite generated from the OpenAPI ' + spec.spec_version + ' document',
  ' * for ' + spec.api_title + '.',
  ' *',
  ' * ' + spec.deterministic_count + ' tests across ' + spec.operation_count + ' operations, every one derived from the',
  ' * specification: happy paths, missing required parameters, wrong types,',
  ' * invalid enum values, missing bodies and unauthenticated calls.',
  ' *',
  ' * Set BASE_URL and AUTH_TOKEN, or pass them as -D system properties.',
  ' */',
  'class ' + javaClass + ' {',
  '',
  '    private static final String BASE_URL = System.getProperty("api.baseUrl", "' + spec.base_url + '");',
  '    private static final String AUTH_TOKEN = System.getProperty("api.authToken", "");',
  '',
  javaTests.join('\n\n'),
  '}',
  '',
].join('\n');

// --- summary ----------------------------------------------------------------
const kindLine = Object.keys(spec.tests_by_kind || {})
  .map((k) => (FOLDER_TITLES[k] || k).replace(/^\d+\.\s*/, '') + ': ' + spec.tests_by_kind[k]).join('\n  ');

const telegram_text = [
  'API tests generated - ' + spec.api_title + ' (OpenAPI ' + spec.spec_version + ')',
  '',
  spec.operation_count + ' operations, ' + spec.deterministic_count + ' tests derived from the spec:',
  '  ' + kindLine,
  '',
  scenarios.length + ' scenarios the schema could not imply' +
    (droppedUnknownPath + droppedUnknownParam ? ' (' + (droppedUnknownPath + droppedUnknownParam) + ' rejected for naming things the spec does not declare)' : ''),
  scenarios.slice(0, 4).map((s) => '  [' + s.priority + '] ' + s.name).join('\n'),
  '',
  arr(model.gaps).length ? 'Gaps for the API owner:\n' + arr(model.gaps).slice(0, 4).map((g, i) => '  ' + (i + 1) + '. ' + g).join('\n') : 'No gaps raised.',
  '',
  'Base URL: ' + spec.base_url,
  'Run with: newman run collection.json --env-var authToken=...',
].join('\n');

return [{
  json: {
    api_title: spec.api_title,
    spec_version: spec.spec_version,
    base_url: spec.base_url,
    operation_count: spec.operation_count,
    deterministic_count: spec.deterministic_count,
    tests_by_kind: spec.tests_by_kind,
    scenario_count: scenarios.length,
    scenarios,
    scenarios_rejected: rejected,
    sequence_notes: str(model.sequence_notes, 'Not Provided'),
    data_notes: str(model.data_notes, 'Not Provided'),
    gaps: arr(model.gaps).map((g) => String(g).trim()).filter(Boolean).slice(0, 6),
    validation_notes: notes.length ? notes : ['No corrections were needed'],
    postman_collection: collection,
    postman_json: JSON.stringify(collection, null, 2),
    restassured_java: restAssured,
    collection_filename: javaName(spec.api_title) + '_postman_collection.json',
    java_filename: javaClass + '.java',
    telegram_text,
  },
}];

const r = $('Build Collection').first().json;

const file = (text, fileName, mimeType) => ({
  data: Buffer.from(String(text), 'utf8').toString('base64'),
  fileName,
  mimeType,
  fileExtension: fileName.split('.').pop(),
});

return [{
  json: r,
  binary: {
    collection: file(r.postman_json, r.collection_filename, 'application/json'),
    javaSuite: file(r.restassured_java, r.java_filename, 'text/x-java-source'),
  },
}];
